insert into public.site_content (content_type, title, body, is_verified, is_published, sort_order) values
('faq', 'What is LTR Growth?', '{"answer":"LTR Growth is an AI marketing platform built by LTRMarketing. It brings ad creation, content planning, website and SEO audits, competitor research, marketing strategy and campaign tracking into one dashboard that is personalized to your business."}', true, true, 1),
('faq', 'Do I need marketing experience to use it?', '{"answer":"No. You describe your business once during onboarding and every tool uses that context. Each recommendation explains what to do and why, so you can act on it yourself or hand it to your team."}', true, true, 2),
('faq', 'Does LTR Growth publish ads or posts for me?', '{"answer":"Not in the initial release. You generate, edit and export content, then publish it on your own accounts. LTR Growth never claims something was published or scheduled unless a connected, authorized integration confirms it."}', true, true, 3),
('faq', 'Where do audit results come from?', '{"answer":"Audits are based on data retrieved from your website and verified sources such as Google PageSpeed Insights. Any check that could not be completed is marked as unverified rather than guessed."}', true, true, 4),
('faq', 'Can you guarantee results?', '{"answer":"No. Nobody can honestly guarantee advertising or revenue outcomes. LTR Growth gives you better-informed recommendations and faster execution; results depend on your market, offer and budget."}', true, true, 5),
('faq', 'What are credits?', '{"answer":"Each AI generation uses credits from your monthly allowance. Calculators never use credits. Allowances reset each billing period, and additional credits can be purchased on paid plans."}', true, true, 6),
('faq', 'Can I cancel anytime?', '{"answer":"Yes. Paid plans are billed monthly through Stripe and can be cancelled from the billing portal. You keep access until the end of the period you paid for."}', true, true, 7),
('faq', 'Can the LTRMarketing team do the work for me?', '{"answer":"Yes. If you would rather have experts handle advertising, SEO, web design or content, you can request a free consultation with LTRMarketing from inside the platform."}', true, true, 8);
